CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS districts (id bigserial PRIMARY KEY, name text NOT NULL UNIQUE, name_as text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone_e164 text UNIQUE NOT NULL, display_name text, avatar_url text, language text NOT NULL DEFAULT 'as' CHECK(language IN ('as','en')), district_id bigint REFERENCES districts(id), locality text, pin_code text, role text NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','seller','admin','moderator')), privacy jsonb NOT NULL DEFAULT '{}', is_banned boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS otp_challenges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone_e164 text NOT NULL, code_hash text NOT NULL, expires_at timestamptz NOT NULL, attempts int NOT NULL DEFAULT 0, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS otp_phone_created_idx ON otp_challenges(phone_e164, created_at DESC);
CREATE TABLE IF NOT EXISTS shops (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, owner_name text NOT NULL, phone_e164 text NOT NULL, cover_url text, avatar_url text, district_id bigint NOT NULL REFERENCES districts(id), locality text NOT NULL, address text, landmark text, latitude double precision, longitude double precision, description text, opening_hours jsonb NOT NULL DEFAULT '{}', fulfillment jsonb NOT NULL DEFAULT '{"pickup":true,"delivery":false}', delivery_charge_paise bigint CHECK(delivery_charge_paise IS NULL OR delivery_charge_paise>=0), delivery_eta_minutes int, status text NOT NULL DEFAULT 'pending_payment' CHECK(status IN ('pending_payment','active','paused','suspended','expired')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS shops_district_idx ON shops(district_id, status);
CREATE INDEX IF NOT EXISTS shops_geo_idx ON shops(latitude,longitude);
CREATE TABLE IF NOT EXISTS shop_memberships (shop_id uuid REFERENCES shops(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE CASCADE, member_role text NOT NULL DEFAULT 'owner', PRIMARY KEY(shop_id,user_id));
CREATE TABLE IF NOT EXISTS categories (id bigserial PRIMARY KEY, slug text UNIQUE NOT NULL, name text NOT NULL, name_as text NOT NULL, restrictions jsonb NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE, category_id bigint REFERENCES categories(id), title text NOT NULL, title_as text, description text, price_paise bigint NOT NULL CHECK(price_paise>=0), unit text NOT NULL DEFAULT 'piece', stock_quantity numeric(14,3) NOT NULL DEFAULT 0 CHECK(stock_quantity>=0), available boolean NOT NULL DEFAULT true, paused boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS products_shop_idx ON products(shop_id, available, paused);
CREATE INDEX IF NOT EXISTS products_search_idx ON products USING gin(to_tsvector('simple', coalesce(title,'') || ' ' || coalesce(description,'')));
CREATE TABLE IF NOT EXISTS media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id uuid NOT NULL REFERENCES users(id), shop_id uuid REFERENCES shops(id) ON DELETE CASCADE, product_id uuid REFERENCES products(id) ON DELETE CASCADE, post_id uuid, storage_key text NOT NULL, media_type text NOT NULL CHECK(media_type IN ('image','video')), mime_type text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes>0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS inventory_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id), quantity_delta numeric(14,3) NOT NULL, reason text NOT NULL, actor_user_id uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_number bigserial UNIQUE, customer_user_id uuid NOT NULL REFERENCES users(id), shop_id uuid NOT NULL REFERENCES shops(id), status text NOT NULL DEFAULT 'placed' CHECK(status IN ('placed','accepted','rejected','preparing','ready_for_pickup','dispatched','completed','cancelled')), subtotal_paise bigint NOT NULL CHECK(subtotal_paise>=0), delivery_charge_paise bigint NOT NULL DEFAULT 0 CHECK(delivery_charge_paise>=0), total_paise bigint NOT NULL CHECK(total_paise>=0), fulfillment_method text NOT NULL CHECK(fulfillment_method IN ('pickup','delivery')), delivery_address jsonb, customer_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_customer_idx ON orders(customer_user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS orders_shop_idx ON orders(shop_id, status, created_at DESC);
CREATE TABLE IF NOT EXISTS order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES products(id), title_snapshot text NOT NULL, unit_snapshot text NOT NULL, quantity numeric(14,3) NOT NULL CHECK(quantity>0), unit_price_paise bigint NOT NULL CHECK(unit_price_paise>=0), line_total_paise bigint NOT NULL CHECK(line_total_paise>=0));
CREATE TABLE IF NOT EXISTS payment_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), shop_id uuid REFERENCES shops(id), order_id uuid REFERENCES orders(id), provider text NOT NULL, provider_order_id text UNIQUE, provider_payment_id text UNIQUE, amount_paise bigint NOT NULL CHECK(amount_paise>=0), currency char(3) NOT NULL DEFAULT 'INR', status text NOT NULL DEFAULT 'created' CHECK(status IN ('created','pending','succeeded','failed','refunded')), idempotency_key text UNIQUE NOT NULL, receipt text, verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_webhooks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, event_id text NOT NULL, payload jsonb NOT NULL, signature_valid boolean NOT NULL, processed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,event_id));
CREATE TABLE IF NOT EXISTS subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shop_id uuid NOT NULL REFERENCES shops(id), payment_attempt_id uuid REFERENCES payment_attempts(id), amount_paise bigint NOT NULL CHECK(amount_paise>=0), starts_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, status text NOT NULL CHECK(status IN ('active','expired','cancelled','pending')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS subscriptions_shop_expiry_idx ON subscriptions(shop_id, expires_at DESC);
CREATE TABLE IF NOT EXISTS referrals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), referrer_user_id uuid NOT NULL REFERENCES users(id), referred_user_id uuid UNIQUE REFERENCES users(id), referral_code text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','paid','expired')), eligible_payment_id uuid REFERENCES payment_attempts(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS referral_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), referral_id uuid REFERENCES referrals(id), user_id uuid NOT NULL REFERENCES users(id), direction text NOT NULL CHECK(direction IN ('credit','debit')), amount_paise bigint NOT NULL CHECK(amount_paise>0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','available','reserved','paid','reversed')), idempotency_key text UNIQUE NOT NULL, note text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS referral_ledger_user_idx ON referral_ledger(user_id,status,created_at);
CREATE TABLE IF NOT EXISTS withdrawal_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), amount_paise bigint NOT NULL CHECK(amount_paise>=50000), payout_method text NOT NULL, payout_reference text, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','processing','paid','failed')), reviewed_by uuid REFERENCES users(id), reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), body text, visibility text NOT NULL DEFAULT 'public' CHECK(visibility IN ('public','followers','private')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','published','removed','rejected')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS community_feed_idx ON community_posts(status,created_at DESC);
CREATE TABLE IF NOT EXISTS comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES community_posts(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, status text NOT NULL DEFAULT 'published', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS likes (user_id uuid REFERENCES users(id) ON DELETE CASCADE, post_id uuid REFERENCES community_posts(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,post_id));
CREATE TABLE IF NOT EXISTS follows (follower_user_id uuid REFERENCES users(id) ON DELETE CASCADE, followed_user_id uuid REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(follower_user_id,followed_user_id), CHECK(follower_user_id<>followed_user_id));
CREATE TABLE IF NOT EXISTS reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_user_id uuid NOT NULL REFERENCES users(id), target_type text NOT NULL, target_id uuid NOT NULL, reason text NOT NULL, details text, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','reviewing','resolved','dismissed')), reviewed_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL, title text NOT NULL, body text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS notifications_user_idx ON notifications(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS admin_roles (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('admin','moderator','finance','support')), granted_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY, actor_user_id uuid REFERENCES users(id), action text NOT NULL, target_type text, target_id text, request_id text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app_settings (key text PRIMARY KEY, value jsonb NOT NULL, updated_by uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO districts(name,name_as) VALUES
('Baksa','বাক্সা'),('Bajali','বজালী'),('Barpeta','বৰপেটা'),('Biswanath','বিশ্বনাথ'),('Bongaigaon','বঙাইগাঁও'),('Cachar','কাছাৰ'),('Charaideo','চৰাইদেউ'),('Chirang','চিৰাং'),('Darrang','দৰং'),('Dhemaji','ধেমাজি'),('Dhubri','ধুবুৰী'),('Dibrugarh','ডিব্ৰুগড়'),('Dima Hasao','ডিমা হাছাও'),('Goalpara','গোৱালপাৰা'),('Golaghat','গোলাঘাট'),('Hailakandi','হাইলাকান্দি'),('Hojai','হোজাই'),('Jorhat','যোৰহাট'),('Kamrup','কামৰূপ'),('Kamrup Metropolitan','কামৰূপ মহানগৰ'),('Karbi Anglong','কাৰ্বি আংলং'),('Kokrajhar','কোকৰাঝাৰ'),('Lakhimpur','লখিমপুৰ'),('Majuli','মাজুলী'),('Morigaon','মৰিগাঁও'),('Nagaon','নগাঁও'),('Nalbari','নলবাৰী'),('Sivasagar','শিৱসাগৰ'),('Sonitpur','শোণিতপুৰ'),('South Salmara-Mankachar','দক্ষিণ শালমাৰা-মানকাচৰ'),('Sribhumi','শ্ৰীভূমি'),('Tamulpur','তামুলপুৰ'),('Tinsukia','তিনিচুকীয়া'),('Udalguri','ওদালগুৰি'),('West Karbi Anglong','পশ্চিম কাৰ্বি আংলং') ON CONFLICT(name) DO UPDATE SET name_as=EXCLUDED.name_as;
INSERT INTO categories(slug,name,name_as,restrictions) VALUES
('handloom','Handloom & Gamusa','হাততাঁত আৰু গামোচা','{}'),('handicrafts','Handicrafts','হস্তশিল্প','{}'),('vegetables','Vegetables','শাক-পাচলি','{"food_safety_ack":true}'),('fruits','Fruits','ফল-মূল','{"food_safety_ack":true}'),('rice-grains','Rice & Grains','চাউল আৰু শস্য','{"food_safety_ack":true}'),('eggs-poultry','Eggs & Poultry','কণী আৰু হাঁহ-কুকুৰা','{"food_safety_ack":true,"licence_check_configurable":true}'),('traditional-food','Pitha & Traditional Food','পিঠা আৰু পৰম্পৰাগত খাদ্য','{"food_safety_ack":true}'),('groceries','Groceries','মুদী সামগ্ৰী','{"regulated_goods_check":true}'),('clothing','Clothing','কাপোৰ','{}'),('electronics','Electronics','ইলেক্ট্ৰনিক সামগ্ৰী','{}'),('services','Services','সেৱা','{}'),('other-lawful','Other lawful goods','অন্যান্য বৈধ সামগ্ৰী','{"admin_review":true}') ON CONFLICT(slug) DO NOTHING;
